n=27
G=[[4]*n for _ in range(n)]
for c in range(n): G[13][c]=1
for r in range(n): G[r][13]=1
# Template in top-left quadrant, including its 2x2 core
for r,c,v in [(3,6,7),(4,5,8),(4,6,7)]: G[r][c]=v
for r in (5,6):
    G[r][4]=9
    for c in (5,6): G[r][c]=2
    for c in (7,8): G[r][c]=1
# Other color-2 cores from the test
for r in (5,6):
    for c in (20,21): G[r][c]=2
for r in range(19,23):
    for c in range(4,8): G[r][c]=2
for r in (20,21):
    for c in (19,20): G[r][c]=2
# Copy every non-background/non-core template pixel around each core, scaled to its size,
# with reflections for its quadrant.
source_core=(5,5,2) # top, left, side
source=[]
for r in range(3,9):
    for c in range(4,9):
        v=G[r][c]
        if v!=4 and not (5<=r<7 and 5<=c<7): source.append((r-5,c-5,v))
# targets: top,left,side, flip vertically, flip horizontally
for top,left,side,fy,fx in [(5,20,2,False,True),(19,4,4,True,False),(20,19,2,True,True)]:
    scale=side//2
    assert side%2==0
    for dy,dx,v in source:
        yy=(side-scale)-dy*scale if fy else dy*scale
        xx=(side-scale)-dx*scale if fx else dx*scale
        for a in range(scale):
            for b in range(scale):
                rr=top+yy+a; cc=left+xx+b
                if 0<=rr<n and 0<=cc<n:
                    if G[rr][cc] not in (4,v):
                        print('OVERLAP',rr,cc,G[rr][cc],v)
                    G[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in G))
